[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath,[Parameter(Mandatory=$true)][string]$OutputDirectory,[switch]$BindingSmokeOnly)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$ProjectPath=[IO.Path]::GetFullPath($ProjectPath);$OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory);$base=[IO.Path]::GetFullPath((Join-Path $ProjectPath 'Research\Verification\Gate13R_48h_10pct_3Lane_PreImplementation\v1'));if(-not$OutputDirectory.StartsWith($base.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Binding output escapes preimplementation root.'};if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate13R48h3LaneBindingSmokeV1|$OutputDirectory");exit 0};if(Test-Path $OutputDirectory){throw 'Create-new binding output exists.'};New-Item -ItemType Directory -Path $OutputDirectory|Out-Null
$ps='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe';$verification=Join-Path $ProjectPath 'Research\Verification\Gate13R_48h_10pct_3Lane\v1';$lane='H:\DDM_Final_Project_Gate13R48H\v1\lane-01';$barrier=Join-Path $verification '_binding\wave';$blockOutput=Join-Path $barrier 'block';$planPath=Join-Path $verification '_binding\plan.json';$rows=New-Object Collections.Generic.List[object]
$cases=@(
 [pscustomobject]@{name='plan-generator';script='Research\Verification\New-Gate13R48h3LanePlanV1.ps1';args=@('-ProjectPath',$ProjectPath)},
 [pscustomobject]@{name='schedule-generator';script='Research\Verification\New-Gate13R48h3LaneScheduleV1.ps1';args=@('-ProjectPath',$ProjectPath)},
 [pscustomobject]@{name='provenance-generator';script='Research\Verification\New-Gate13R48h3LaneProvenanceV1.ps1';args=@('-ProjectPath',$ProjectPath)},
 [pscustomobject]@{name='compile';script='Research\Verification\Run-Gate13R48h3LaneCompileV1.ps1';args=@('-ProjectPath',$ProjectPath,'-VerificationRoot',(Join-Path $base 'BindingCompile'))},
 [pscustomobject]@{name='static';script='Research\Verification\Run-Gate13R48h3LaneStaticUnitV1.ps1';args=@('-ProjectPath',$ProjectPath,'-OutputDirectory',(Join-Path $base 'BindingStatic'))},
 [pscustomobject]@{name='initializer';script='Research\Initialize-Gate13R48h3LaneCopiesV1.ps1';args=@('-ProjectPath',$ProjectPath,'-CloneRoot','H:\DDM_Final_Project_Gate13R48H\v1','-VerificationOutputRoot',(Join-Path $verification 'BindingCopies'))},
 [pscustomobject]@{name='telemetry';script='Research\Run-Gate13R48h3LaneTelemetryProbeV1.ps1';args=@('-LaneProjectPath',$lane,'-OutputDirectory',(Join-Path $lane 'Research\Verification\Gate13R_48h_10pct_3Lane\v1\BindingTelemetry'),'-LaneNumber','1','-AffinityMaskHex','0x000000FF')},
 [pscustomobject]@{name='bootstrap';script='Research\Verification\Run-Gate13R48h3LaneBootstrapCompileV1.ps1';args=@('-LaneProjectPath',$lane,'-OutputPrefix',(Join-Path $lane 'Research\Verification\Gate13R_48h_10pct_3Lane\v1\BindingBootstrap'),'-LaneNumber','1','-AffinityMaskHex','0x000000FF')},
 [pscustomobject]@{name='block';script='Research\Run-Gate13R48h3LaneBlockV1.ps1';args=@('-BlockPlanPath',$planPath,'-OutputDirectory',$blockOutput,'-AllowedRoot',$verification,'-Mode','Verification','-SourceProjectPath',$ProjectPath,'-LaneProjectPath',$lane,'-LaneNumber','1','-AffinityMaskHex','0x000000FF','-WaveId','binding-wave','-BarrierToken','binding-token','-BarrierRoot',$barrier)},
 [pscustomobject]@{name='license-probe';script='Research\Run-Gate13R48h3LaneLicenseProbeV1.ps1';args=@('-OutputDirectory',(Join-Path $barrier 'probe'),'-AllowedRoot',$verification,'-LaneProjectPath',$lane,'-LaneNumber','1','-AffinityMaskHex','0x000000FF','-WaveId','binding-wave','-BarrierToken','binding-token','-BarrierRoot',$barrier)},
 [pscustomobject]@{name='licensing-stress';script='Research\Verification\Run-Gate13R48h3LaneLicensingStressV1.ps1';args=@('-ProjectPath',$ProjectPath,'-OutputRoot',(Join-Path $verification 'LicensingStress'))},
 [pscustomobject]@{name='retained-regression';script='Research\Verification\Run-Gate13R48h3LaneRetainedRegressionV1.ps1';args=@('-ProjectPath',$ProjectPath,'-OutputDirectory',(Join-Path $verification 'RetainedRegression'))},
 [pscustomobject]@{name='verification';script='Research\Verification\Run-Gate13R48h3LaneVerificationV1.ps1';args=@('-ProjectPath',$ProjectPath)},
 [pscustomobject]@{name='validation-only-audit';script='Research\Verification\Run-Gate13R48h3LaneValidationOnlyPrePilotAuditV1.ps1';args=@('-ProjectPath',$ProjectPath,'-VerificationRoot',$verification)},
 [pscustomobject]@{name='pilot';script='Research\Run-Gate13R48h3LanePilotV1.ps1';args=@('-ProjectPath',$ProjectPath,'-PrePilotAuditPath',(Join-Path $verification 'audit.json'),'-LicensingStressManifestPath',(Join-Path $verification 'stress.json'))},
 [pscustomobject]@{name='analyzer';script='Research\Analyze-Gate13R48h3LanePilotV1.ps1';args=@('-ProjectPath',$ProjectPath,'-PilotRoot',(Join-Path $ProjectPath 'Research\PilotRuns\Gate13R_48h_10pct_3Lane\v1'))},
 [pscustomobject]@{name='stabilization';script='Research\Verification\Wait-Gate13R48h3LaneEnvironmentStabilizationV1.ps1';args=@('-ProjectPath',$ProjectPath,'-VerificationRoot',$verification)}
)
foreach($case in $cases){$scriptPath=Join-Path $ProjectPath $case.script;$stdout=Join-Path $OutputDirectory ($case.name+'.stdout.log');$stderr=Join-Path $OutputDirectory ($case.name+'.stderr.log');$arguments=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$scriptPath)+@($case.args)+@('-BindingSmokeOnly');$process=Start-Process -FilePath $ps -ArgumentList $arguments -WorkingDirectory $ProjectPath -WindowStyle Hidden -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru -Wait;$stdoutText=if(Test-Path $stdout){Get-Content -Raw $stdout}else{''};$stderrText=if(Test-Path $stderr){Get-Content -Raw $stderr}else{''};$output=$stdoutText+$stderrText;$passed=[int]$process.ExitCode-eq0-and$output-like'*BINDING-SMOKE-PASSED*';$rows.Add([pscustomobject]@{name=$case.name;script=$case.script;exitCode=[int]$process.ExitCode;stdout=$stdout;stderr=$stderr;output=$output.Trim();passed=$passed})}
$fail=@($rows|Where-Object passed -ne $true);$summary=[ordered]@{schemaVersion=1;summaryKind='gate13r-48h-three-lane-windows-powershell51-binding-smoke-v1';completedAtUtc=[DateTime]::UtcNow.ToString('o');caseCount=$rows.Count;failedCaseCount=$fail.Count;cases=$rows.ToArray();unityProcessCountAfter=@(Get-Process Unity -ErrorAction SilentlyContinue).Count;formalCampaign=$false;passed=$fail.Count-eq0-and@(Get-Process Unity -ErrorAction SilentlyContinue).Count-eq0};$json=($summary|ConvertTo-Json -Depth 30).Replace("`r`n","`n").Replace("`r","`n")+"`n";[IO.File]::WriteAllText((Join-Path $OutputDirectory 'summary.json'),$json,(New-Object Text.UTF8Encoding($false,$true)));if(-not$summary.passed){Write-Error ($fail|ConvertTo-Json -Depth 10);exit 1};Write-Host("Binding smoke passed: $($rows.Count) entry points, no Unity launched.")-ForegroundColor Green
